if first_warn_time is not None:
    before_warn_event = events[events['time'] < first_warn_time]
    if not before_warn_event.empty:
        last_before_warn = before_warn_event.iloc[-1]
        component_before = last_before_warn['component']
    else:
        component_before = None
else:
    component_before = None

component_before

